var waveIn = MSD.qa('#sm-wave-in i');
var waveOut = MSD.qa('#sm-wave-out i');
var waveTimer = MSD.every(160, function(){
  waveIn.forEach(function(el){ el.style.height = (10 + Math.random() * 46) + 'px'; });
});
MSD.after(100, function(){ MSD.show('.sm-tline', 260); });
MSD.after(1750, function(){
  clearInterval(waveTimer);
  waveIn.forEach(function(el){ el.style.height = '10px'; });
  var outTimer = MSD.every(150, function(){
    waveOut.forEach(function(el){ el.style.height = (10 + Math.random() * 46) + 'px'; });
  });
  MSD.after(1050, function(){
    clearInterval(outTimer);
    waveOut.forEach(function(el){ el.style.height = '10px'; });
  });
});
